export const MOCK_BADGE_IDS = new Set(MOCK_BADGES.map(badge => badge.id));

export function getMockBadge(id: string): MockBadge | undefined {
    return MOCK_BADGES.find(badge => badge.id === id);
}

/** Turns a raw SVG (or an already-encoded data URL) into an image source.
 * Strips the first <path> (black background circle) from discord-badges SVGs. */
export function badgeDataUrl(svg: string): string {
    if (svg.startsWith("data:")) return svg;
    // Remove the first <path fill="rgb(0, 0, 0)">...</path> which is a black background circle
    const cleaned = svg.replace(/<path[^>]*fill:\s*rgb\(0\s*,\s*0\s*,\s*0\)[^>]*>.*?<\/path>\s*/, "");
    return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(cleaned)}`;
}
